-- Aula 05 · Data Collection and Storage · 07/11/2026 · modelagem relacional e dimensional, com retomada da Aula 04.
-- Usa as tabelas/RPCs existentes no Supabase do aulas_senac. Não execute o schema destrutivo.
-- Reexecução preserva IDs; recusa alterar sala iniciada ou com participantes.
-- O token do professor entra como marcador e é substituído por scripts/quiz_db.mjs a partir do .env.
begin;
select pg_advisory_xact_lock(hashtext('mack-dcs-a05-2026-2'));
do $$ begin if exists (select 1 from quiz_sessions where slug='mack-dcs-a05-2026-2' and (estado <> 'lobby' or pergunta_atual <> 0)) or exists (select 1 from quiz_players where session_slug='mack-dcs-a05-2026-2') then raise exception 'Sala já iniciada ou com participantes: seed cancelado para preservar a rodada.'; end if; end $$;
insert into quiz_sessions (slug,titulo,periodo) values ('mack-dcs-a05-2026-2','Aula 05 — Modelagem relacional e dimensional','2026-2') on conflict (slug) do update set titulo=excluded.titulo;
with novas as (
  insert into quiz_questions (session_slug,ordem,enunciado,alternativas,segundos,tema,secao,peso) values
  ('mack-dcs-a05-2026-2', 1, 'A silver de livros da Aula 04 já é Parquet tipado, deduplicado e com arquivo_origem. Em qual camada do medalhão o esquema estrela desta aula deve ser publicado?', '["Na bronze, porque o JSON Lines aceita colunas novas sem migrar o esquema.", "Na silver, porque ela já tem tipos declarados e um contrato por tabela.", "Na gold, porque ela fica no grão da pergunta de negócio e serve ao consumo.", "Na raw, porque os bytes originais preservam o histórico de cada coleta."]'::jsonb, 90, 'Medalhão e camada gold', 'Aula 04, seção 6; Aula 05, seção 1.2', 1),
  ('mack-dcs-a05-2026-2', 2, 'Uma consulta no DuckDB calcula a média de preco_gbp por categoria lendo a silver em Parquet no MinIO. Que propriedade do formato reduz os bytes baixados do bucket?', '["Projeção de colunas: o leitor baixa só os trechos das colunas pedidas.", "Compressão por linha: cada registro é compactado junto com seu cabeçalho.", "Ordenação por chave: o arquivo é regravado em ordem de UPC a cada carga.", "Índice B-tree no rodapé: o leitor localiza cada linha sem varrer o arquivo."]'::jsonb, 90, 'Parquet e DuckDB', 'Aula 04, seções 4.4, 4.5 e 7', 1),
  ('mack-dcs-a05-2026-2', 3, 'No exemplo numérico 1, com 365.000 observações, a busca do preço atual por UPC levou menos de 1 ms no Postgres e cerca de 3 ms no DuckDB. A agregação por categoria e mês levou cerca de 0,7 s no Postgres e de 28 a 40 ms no DuckDB. O que essa medição autoriza concluir?', '["Que o DuckDB é mais rápido em qualquer carga e pode substituir o Postgres.", "Que o Postgres precisa de mais índices para agregar por categoria e mês.", "Que a diferença vem do volume e desaparece acima de um milhão de linhas.", "Que cada motor favorece um padrão de acesso, nesta carga e nesta máquina."]'::jsonb, 90, 'OLTP e OLAP', 'Aula 05, seção 2, exemplo numérico 1', 1),
  ('mack-dcs-a05-2026-2', 4, 'Na linha plana do scraper, a chave é (upc, data_coleta) e o titulo se repete em todas as coletas do mesmo livro. Qual forma normal essa repetição viola e qual é a correção?', '["1FN; separar o titulo em palavras atômicas, numa tabela própria.", "2FN; mover o titulo para a tabela livro, que depende só do upc.", "3FN; mover o titulo para a tabela categoria, que agrupa os livros.", "2FN; acrescentar o titulo à chave primária para tornar a linha única."]'::jsonb, 90, 'Normalização', 'Aula 05, seção 6, exemplo numérico 2', 1),
  ('mack-dcs-a05-2026-2', 5, 'O modelo relacional usa livro_id como chave primária e upc com UNIQUE. Por que a URL do livro ficou fora da chave?', '["Porque a URL é longa demais para ser indexada pelo PostgreSQL.", "Porque a URL não aparece nas páginas de listagem do site.", "Porque a URL muda com o slug do site e partiria o histórico do livro.", "Porque a URL já identifica a categoria e criaria dependência transitiva."]'::jsonb, 90, 'Chaves naturais e substitutas', 'Aula 05, seção 5', 1),
  ('mack-dcs-a05-2026-2', 6, 'O DDL cria ix_observacao_data, embora a chave primária de observacao_preco já seja (livro_id, data_coleta). Qual é a razão desse índice?', '["A PK começa por livro_id e não atende filtros feitos só por período.", "O PostgreSQL não cria índice para chaves primárias compostas.", "Sem esse índice, a FK para livro deixaria de ser verificada na escrita.", "O índice impede duas observações do mesmo livro no mesmo dia."]'::jsonb, 90, 'Constraints e índices', 'Aula 05, seções 7 e 8, exemplo numérico 3', 1),
  ('mack-dcs-a05-2026-2', 7, 'A carga relacional é reexecutada para o mesmo dia depois de um 502 do proxy. O que garante que observacao_preco não fique com linhas duplicadas?', '["O DISTINCT ON da consulta de staging, que remove repetições do silver.", "A FK fk_observacao_livro, que recusa livros que já foram carregados.", "O índice ix_observacao_data, que torna cada data única na tabela.", "A PK (livro_id, data_coleta), usada pelo INSERT ... ON CONFLICT."]'::jsonb, 90, 'Idempotência pela chave', 'Aula 05, seção 7', 1),
  ('mack-dcs-a05-2026-2', 8, 'Em novembro, a fato_preco_diario tem 30.000 linhas. Somar qtd_estoque nos 30 dias deu 330.243, enquanto o estoque somado dentro de cada dia ficou perto de 11.000. Como essa medida deve ser agregada?', '["Como aditiva: a soma dos 30 dias é o estoque disponível no mês.", "Como semiaditiva: soma dentro do dia; entre dias, média ou último valor.", "Como não aditiva: nunca somar, nem entre livros do mesmo dia.", "Como derivada: dividir a soma do mês pelo número de livros observados."]'::jsonb, 90, 'Tipos de medida', 'Aula 05, seção 11, exemplo numérico 4', 1),
  ('mack-dcs-a05-2026-2', 9, 'Em novembro de 2026, 11 dos 30 dias de coleta não têm PTAX (fins de semana e os feriados de 02/11 e 20/11). Um join por igualdade de data deixou 11.000 observações sem cotação. O que a carga da gold faz?', '["Descarta as observações sem cotação, para que preco_brl nunca fique nulo.", "Aplica a média das cotações do mês a todos os dias, com ou sem PTAX.", "Usa o último fechamento até a coleta (ASOF) e grava data_cotacao_sk.", "Interpola a cotação entre o dia útil anterior e o seguinte à coleta."]'::jsonb, 90, 'Dimensão de data com papéis', 'Aula 05, seção 12, exemplo numérico 5', 1),
  ('mack-dcs-a05-2026-2', 10, 'Um livro passou de Fiction para Mystery em 03/11. Na estrela, categoria é atributo de SCD tipo 2 em dim_livro. Quantas versões o livro passa a ter e em que categoria contam as observações de outubro?', '["Uma versão, atualizada para Mystery; outubro passa a contar como Mystery.", "Duas versões; outubro conta como Mystery, porque vale a versão atual.", "Uma versão por dia de coleta; outubro conta na categoria de cada dia.", "Duas versões, com valido_de e valido_ate; outubro continua em Fiction."]'::jsonb, 90, 'SCD tipo 1 e tipo 2', 'Aula 05, seções 14 e 16, exemplo numérico 6', 2)
  on conflict (session_slug,ordem) do update set enunciado=excluded.enunciado, alternativas=excluded.alternativas, segundos=excluded.segundos, tema=excluded.tema, secao=excluded.secao, peso=excluded.peso
  returning id,ordem
)
insert into quiz_answer_key (question_id,correta,explicacao)
select n.id,g.correta,g.explicacao from novas n join (values
  (1, 2, 'A raw guarda os bytes da fonte e nunca é alterada; a bronze extrai registros ainda sem tipos garantidos; a silver tem contrato por tabela no grão da coleta. A gold está no grão da pergunta de negócio, e é nela que fatos e dimensões ficam: o laboratório publica seis arquivos Parquet em gold no MinIO, conferidos com mc ls.'),
  (2, 0, 'No Parquet, os valores de cada coluna ficam juntos dentro de cada row group, e o rodapé informa onde cada coluna está. O leitor baixa só preco_gbp, categoria e o que a consulta usa. Estatísticas de mínimo e máximo ainda permitem pular row groups; não há índice B-tree, e o arquivo é imutável.'),
  (3, 3, 'O Postgres localiza poucas linhas por índice B-tree; o DuckDB processa colunas em vetores e lê só as colunas da agregação. A medição foi feita com dados sintéticos, mediana de nove execuções, numa única máquina. Ela sustenta uma conclusão sobre essa carga, não um vencedor geral; o cenário CEN-05 pede a mesma medida com o volume do grupo.'),
  (4, 1, 'A 2FN exige que nenhum atributo dependa só de parte da chave composta. O titulo depende apenas do upc, e não da data, e por isso se repete a cada coleta. A decomposição cria livro(upc, titulo, categoria) e deixa em observacao_preco só o que muda por dia.'),
  (5, 2, 'A URL muda quando o site altera o slug ou a estrutura de pastas; usada como chave, cada mudança criaria um livro novo e partiria o histórico em dois. Ela vira atributo, com histórico em livro_url. O UPC é a chave natural estável, protegida por UNIQUE, e livro_id é a chave substituta referenciada pelas FKs.'),
  (6, 0, 'O PostgreSQL cria índice para PRIMARY KEY e UNIQUE, mas não para FOREIGN KEY. Como a PK começa por livro_id, ela serve ao histórico de um livro, e não a todas as observações de outubro. No exemplo numérico 3, a consulta de outubro levou de 5 a 10 ms com o índice e de 15 a 23 ms sem ele; o índice ocupa 2,6 MiB e encarece cada escrita.'),
  (7, 3, 'Com a PK (livro_id, data_coleta), reexecutar o mesmo dia faz o INSERT ... ON CONFLICT DO UPDATE atualizar as mesmas linhas em vez de inserir outras. A idempotência vem da chave escolhida na modelagem; o código da carga apenas a usa. O DISTINCT ON trata repetições dentro de um mesmo lote, não entre execuções.'),
  (8, 1, 'qtd_estoque é semiaditiva: pode ser somada por livro e por categoria dentro de um dia, mas não ao longo dos dias. A soma de 30 dias dá um número 30 vezes maior que qualquer estoque real. A consulta Q7 do laboratório soma por dia e depois usa média ou último valor entre os dias.'),
  (9, 2, 'A carga resolve a regra uma vez: para cada observação, usa a última cotação de fechamento com data menor ou igual à da coleta, com ASOF JOIN no DuckDB. A fato guarda data_coleta_sk e data_cotacao_sk, dois papéis da mesma dim_data, para mostrar qual cotação foi usada. No exemplo numérico 5, nenhuma observação ficou sem cotação e a mais antiga usada tinha 3 dias.'),
  (10, 3, 'No tipo 2, a carga encerra a versão vigente (valido_ate = 02/11, versao_atual = false) e abre outra com nova chave substituta a partir de 03/11. As observações de outubro continuam ligadas à versão Fiction. No modelo relacional, a mesma mudança atualiza livro.categoria_id e todo o histórico passa a contar como Mystery; o tipo 1 fica para avaliacao e url.')
) as g(ordem,correta,explicacao) on g.ordem=n.ordem
on conflict (question_id) do update set correta=excluded.correta, explicacao=excluded.explicacao;
insert into quiz_host_tokens (session_slug,token) values ('mack-dcs-a05-2026-2','__QUIZ_HOST_TOKEN__') on conflict (session_slug) do update set token=excluded.token;
do $$ begin if (select count(*) from quiz_questions where session_slug='mack-dcs-a05-2026-2') <> 10 then raise exception 'A sala deve conter exatamente 10 perguntas'; end if; end $$;
commit;
